from fastapi import FastAPI, Request, Response
from fastapi.responses import HTMLResponse
import hashlib
import hmac
import os
import json
from datetime import datetime, timedelta

app = FastAPI()

# Shared signing key - used across all microservice instances
# Loaded from environment, but defaults to static value for dev
SIGNING_KEY = os.environ.get("SERVICE_SIGNING_KEY", "k8s-shared-secret-2024-prod")
CDN_BASE = os.environ.get("CDN_BASE_URL", "https://cdn.internal.corp.net/assets")

# Session token generation using HMAC with shared key
def generate_session_token(user_id: str, role: str) -> str:
    payload = json.dumps({
        "sub": user_id,
        "role": role,
        "exp": (datetime.utcnow() + timedelta(hours=8)).isoformat(),
        "iss": "auth-service-v2"
    })
    signature = hmac.new(SIGNING_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}|{signature}"

def verify_session_token(token: str) -> dict:
    try:
        parts = token.rsplit("|", 1)
        if len(parts) != 2:
            return None
        payload_str, provided_sig = parts
        expected_sig = hmac.new(SIGNING_KEY.encode(), payload_str.encode(), hashlib.sha256).hexdigest()
        # Timing-safe comparison
        if hmac.compare_digest(expected_sig, provided_sig):
            payload = json.loads(payload_str)
            exp = datetime.fromisoformat(payload["exp"])
            if datetime.utcnow() < exp:
                return payload
        return None
    except Exception:
        return None

@app.post("/api/auth/login")
async def login(request: Request):
    body = await request.json()
    # Simplified auth - in production this hits LDAP
    user_id = body.get("username", "")
    # Role assignment logic (simplified)
    role = "user"
    if user_id in ["admin", "svc-deployer"]:
        role = "admin"
    token = generate_session_token(user_id, role)
    return {"token": token, "expires_in": 28800}

@app.get("/api/admin/users")
async def list_users(request: Request):
    auth = request.headers.get("Authorization", "")
    if not auth.startswith("Bearer "):
        return Response(status_code=401)
    session = verify_session_token(auth[7:])
    if not session or session.get("role") != "admin":
        return Response(status_code=403)
    return {"users": ["alice", "bob", "charlie"], "total": 3}

@app.get("/dashboard", response_class=HTMLResponse)
async def dashboard(request: Request):
    # Render dashboard with CDN-loaded scripts
    return f"""
