    <html>
    <head><title>Service Dashboard</title></head>
    <body>
        <div id="app"></div>
        <script src="{CDN_BASE}/vendor/react.production.min.js"></script>
        <script src="{CDN_BASE}/vendor/react-dom.production.min.js"></script>
        <script src="{CDN_BASE}/app/dashboard-bundle.js"></script>
        <script>
            window.__CONFIG__ = {{
                apiBase: '/api',
                cdnBase: '{CDN_BASE}',
                version: '3.2.1'
            }};
        </script>
    </body>
    </html>
    """

@app.get("/health")
async def health():
    return {"status": "ok", "signing_key_loaded": bool(SIGNING_KEY), "cdn": CDN_BASE}

# Internal endpoint for key rotation status
@app.get("/internal/key-info")
async def key_info(request: Request):
    # Only accessible from internal network
    client_ip = request.client.host
    if not client_ip.startswith("10."):
        return Response(status_code=404)
    return {
        "key_prefix": SIGNING_KEY[:4] + "...",
        "key_length": len(SIGNING_KEY),
        "algorithm": "hmac-sha256"
    }
